mapper.select:
SELECT s.balance_id,b.location_id,b.owner_id,b.sku_id,b.lot_id,b.quality_code FROM local_serial s JOIN stock_balance b
  ON b.enterprise_id=s.enterprise_id AND b.warehouse_id=s.warehouse_id AND b.id=s.balance_id
WHERE s.enterprise_id=#{e} AND s.warehouse_id=#{w} AND s.serial_id=#{serial}

SELECT id,serial_id,sku_id,release_ref,transfer_id,from_epoch,target_warehouse_id,context_hash,state,claim_epoch,attempts
FROM serial_release_intent WHERE enterprise_id=#{e} AND warehouse_id=#{w}
AND state IN ('PENDING','RUNNING') AND next_attempt_at <= #{now}
ORDER BY next_attempt_at,id LIMIT 1 FOR UPDATE SKIP LOCKED
